CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,full_name TEXT NOT NULL,email TEXT NOT NULL COLLATE NOCASE UNIQUE,phone TEXT NOT NULL,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_auth_sessions_expiry ON auth_sessions(expires_at);
CREATE TABLE IF NOT EXISTS wallets(user_id TEXT PRIMARY KEY REFERENCES customers(id) ON DELETE CASCADE,balance_kobo INTEGER NOT NULL DEFAULT 0 CHECK(balance_kobo>=0),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wallet_ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES customers(id),reference TEXT NOT NULL UNIQUE,type TEXT NOT NULL CHECK(type IN('credit','debit')),amount_kobo INTEGER NOT NULL CHECK(amount_kobo>0),description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'success',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_wallet_ledger_user ON wallet_ledger(user_id,id DESC);
CREATE TABLE IF NOT EXISTS wallet_topups(reference TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES customers(id),amount_kobo INTEGER NOT NULL CHECK(amount_kobo>=50000),status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wallet_orders(reference TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES customers(id),service TEXT NOT NULL CHECK(service IN('data','airtime')),network TEXT NOT NULL,phone TEXT NOT NULL,product_id TEXT NOT NULL,amount_kobo INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'processing',provider_reference TEXT,provider_response TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);